{"command": "create", "path": "/app/frontend/src/lib/api.ts", "file_text": "import type { Habit, Dashboard, LoginRequest, LoginResponse, CreateHabit, UpdateHabit, Completion } from '../types';

const API_BASE = '/api';

class ApiError extends Error {
  constructor(public status: number, message: string) {
    super(message);
    this.name = 'ApiError';
  }
}

let authToken: string | null = localStorage.getItem('auth_token');
let onUnauthorized: (() => void) | null = null;

export function setAuthToken(token: string | null) {
  authToken = token;
  if (token) {
    localStorage.setItem('auth_token', token);
  } else {
    localStorage.removeItem('auth_token');
  }
}

export function getAuthToken(): string | null {
  return authToken;
}

export function setOnUnauthorized(callback: () => void) {
  onUnauthorized = callback;
}

async function fetchApi<T>(
  endpoint: string,
  options: RequestInit = {}
): Promise<T> {
  const headers: Record<string, string> = {
    'Content-Type': 'application/json',
    ...(options.headers as Record<string, string>),
  };

  if (authToken) {
    headers['Authorization'] = `Bearer ${authToken}`;
  }

  const response = await fetch(`${API_BASE}${endpoint}`, {
    ...options,
    headers,
  });

  if (response.status === 401 || response.status === 403) {
    if (onUnauthorized) {
      onUnauthorized();
    }
    throw new ApiError(response.status, 'Unauthorized');
  }

  if (!response.ok) {
    const errorData = await response.json().catch(() => ({ message: 'Request failed' }));
    throw new ApiError(response.status, errorData.message || errorData.error || 'Request failed');
  }

  if (response.status === 204) {
    return {} as T;
  }

  return response.json();
}

export const api = {
  login: (data: LoginRequest): Promise<LoginResponse> =>
    fetchApi('/auth/login', { method: 'POST', body: JSON.stringify(data) }),

  getHabits: (): Promise<Habit[]> =>
    fetchApi('/habits'),

  getHabit: (id: string): Promise<Habit> =>
    fetchApi(`/habits/${id}`),

  createHabit: (data: CreateHabit): Promise<Habit> =>
    fetchApi('/habits', { method: 'POST', body: JSON.stringify(data) }),

  updateHabit: (id: string, data: UpdateHabit): Promise<Habit> =>
    fetchApi(`/habits/${id}`, { method: 'PATCH', body: JSON.stringify(data) }),

  deleteHabit: (id: string): Promise<void> =>
    fetchApi(`/habits/${id}`, { method: 'DELETE' }),

  completeHabit: (id: string, date: string): Promise<Completion | { current_streak: number }> =>
    fetchApi(`/habits/${id}/complete`, { method: 'POST', body: JSON.stringify({ date }) }),

  uncompleteHabit: (id: string, date: string): Promise<void> =>
    fetchApi(`/habits/${id}/complete`, { method: 'DELETE', body: JSON.stringify({ date }) }),

  getDashboard: (): Promise<Dashboard> =>
    fetchApi('/dashboard'),

  getCompletions: (habitId: string): Promise<Completion[]> =>
    fetchApi(`/habits/${habitId}/completions`),

  health: (): Promise<{ status: string }> =>
    fetchApi('/health'),
};

export { ApiError };
