{"command": "create", "path": "/app/frontend/src/lib/auth.tsx", "file_text": "import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import { setAuthToken, getAuthToken, setOnUnauthorized, api } from './api';

interface User {
  id: string;
  email: string;
}

interface AuthContextType {
  user: User | null;
  isLoading: boolean;
  login: (email: string, password: string) => Promise<void>;
  logout: () => void;
  sessionExpired: boolean;
  clearSessionExpired: () => void;
}

const AuthContext = createContext<AuthContextType | null>(null);

export function AuthProvider({ children }: { children: React.ReactNode }) {
  const [user, setUser] = useState<User | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [sessionExpired, setSessionExpired] = useState(false);

  const logout = useCallback(() => {
    setAuthToken(null);
    setUser(null);
    localStorage.removeItem('user');
  }, []);

  useEffect(() => {
    const token = getAuthToken();
    const storedUser = localStorage.getItem('user');
    if (token && storedUser) {
      try {
        setUser(JSON.parse(storedUser));
      } catch {
        logout();
      }
    }
    setIsLoading(false);

    setOnUnauthorized(() => {
      logout();
      setSessionExpired(true);
    });
  }, [logout]);

  const login = async (email: string, password: string) => {
    const response = await api.login({ email, password });
    setAuthToken(response.access_token);
    const userData = response.user || { id: '', email };
    setUser(userData);
    localStorage.setItem('user', JSON.stringify(userData));
    setSessionExpired(false);
  };

  const clearSessionExpired = () => setSessionExpired(false);

  return (
    <AuthContext.Provider value={{ user, isLoading, login, logout, sessionExpired, clearSessionExpired }}>
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth() {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
}
